body.script:
(function(){
  function dec(b){var s=atob(b);var a=new Uint8Array(s.length);for(var i=0;i<s.length;i++)a[i]=s.charCodeAt(i);return new TextDecoder().decode(a)}
  var frame=document.getElementById("fusion-embed-frame");
  var html=dec("");
  var base=new URL("./",location.href).href.replace(/\/+$/,"")+"/";
  var p=new URLSearchParams(location.search);
  var target=p.get("target")||"";
  var wisp=p.get("wisp")||"wss://anura.pro/wisp/";
  var transport=p.get("transport")||"libcurl";
  function send(data){if(window.parent!==window)window.parent.postMessage(data,"*")}
  function inject(){
    var head='<base href="'+base+'"/>'+
      '<script>window.__FUSION_TARGET='+JSON.stringify(target)+';window.__FUSION_WISP='+JSON.stringify(wisp)+';window.__FUSION_TRANSPORT='+JSON.stringify(transport)+';</'+'script>';
    frame.srcdoc=html.replace("<head>","<head>"+head);
  }
  window.addEventListener("message",function(e){
    if(e.source!==frame.contentWindow)return;
    var d=e.data||{};
    if(d.type!=="fusion-embed")return;
    send(d);
  });
  inject();
})();
